import { SeedApiClient } from "../../../src/Client";
import { mockServerPool } from "../../mock-server/MockServerPool";
import { mockOAuth } from "../mockAuth";

describe("OauthClient", () => {
    test("getToken", async () => {
        const server = mockServerPool.createServer();
        mockOAuth(server);

        const client = new SeedApiClient({
            maxRetries: 0,
            clientId: "client_id",
            clientSecret: "client_secret",
            environment: server.baseUrl,
        });
        const rawRequestBody = { client_id: "client_id", client_secret: "client_secret" };
        const rawResponseBody = { access_token: "access_token", expires_in: 1 };

        server
            .mockEndpoint()
            .post("/oauth/token")
            .formUrlEncodedBody(rawRequestBody)
            .respondWith()
            .statusCode(200)
            .jsonBody(rawResponseBody)
            .build();

        const response = await client.oauth.getToken({
            client_id: "client_id",
            client_secret: "client_secret",
        });
        expect(response).toEqual(rawResponseBody);
    });
});
